&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;01194a30-6d23-4f85-a7dc-5b504a2b6991&quot; data-indent-level=&quot;1&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;3067&quot; data-local-id=&quot;4c597db4-5de7-44c8-899b-36a8354731d6&quot;&gt;Experience implementing CIC/Auth0&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;3104&quot; data-local-id=&quot;836c3009-42cf-415e-9d06-ac1b533de019&quot;&gt;Previous employment in identity, security, or adjacent companies&lt;br&gt;&lt;br&gt;&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;/li&gt;
